function discoveryWords(seed){
 // Choose genuinely distinct entries in linear time; avoid repeated spelling variants.
 const candidates=[], seen=new Set(), knownBase=new Set();
 for(const row of W){
   const word=String(row[0]||'').replace(/[ً-ٰٟـ]/g,'').trim();
   if(word.length>=3) knownBase.add(N(word));
 }
 const prefixes=['وال','بال','كال','فال','لل','ال','و','ف','ب','ك','ل'];
 for(let i=0;i<W.length;i++){
   const row=W[i], word=String(row[0]||'').replace(/[ً-ٰٟـ]/g,'').trim(), meaning=String(row[1]||'').trim();
   const key=N(word);
   if(word.length<3||meaning.length<12||seen.has(key))continue;
   let attached=false;
   for(const pre of prefixes){
     if(word.startsWith(pre)&&word.length-pre.length>=3&&knownBase.has(N(word.slice(pre.length)))){attached=true;break;}
   }
   if(attached)continue;
   seen.add(key); candidates.push(i);
 }
 if(candidates.length<=6)return candidates;
 const startAt=(Math.abs(seed)*7)%candidates.length, out=[], usedRoots=new Set();
 for(let step=0;out.length<6&&step<candidates.length;step++){
   const idx=candidates[(startAt+step*97)%candidates.length], w=W[idx], root=String(w[4]||'').replace(/\s/g,'');
   if(root&&usedRoots.has(root))continue;
   if(root)usedRoots.add(root);out.push(idx);
 }
 return out;
}
