const wrap=(h,t)=>`<main><div class="page">${t?`<h1>${t}</h1>`:''}${h}</div></main>`;
let wordMatches=[],wordPage=0;const WORD_PAGE_SIZE=100;
function renderWordPage(){const list=$('#wl');if(!list)return;const shown=wordMatches.slice(0,(wordPage+1)*WORD_PAGE_SIZE);list.innerHTML=shown.map(i=>wc(i)).join('')||'<p>لا نتائج. جرّب كلمة أخرى.</p>';const old=$('#wordMore');if(old)old.remove();if(shown.length<wordMatches.length){const b=document.createElement('button');b.id='wordMore';b.className='btn';b.style.margin='22px auto';b.style.display='block';b.textContent=`عرض المزيد (${shown.length} من ${wordMatches.length})`;b.onclick=()=>{wordPage++;renderWordPage();};list.after(b);}reveal()}
function words(){wordMatches=W.map((_,i)=>i);wordPage=0;setTimeout(renderWordPage,0);return wrap(`<div class="sb" style="margin:0 0 20px;border-color:var(--gold2)"><input id="wf" placeholder="ابحث في الكلمات ..." style="color:var(--pageink)" oninput="fw(this.value)"></div><div class="meta" id="wordCount"></div><div class="grid" id="wl" style="max-width:1100px"></div>`,'اكتشف اللغة العربية')}
