function word(i){const w=W[i];if(!w)return wrap('<p>الكلمة غير موجودة.</p>');
return wrap(`<div class="card" style="padding:28px">${fb('w'+i)}<h3 style="font-size:20px;color:var(--gold2)">المعنى</h3><p style="font-size:22px">${w[1]}</p>${w[4]?`<h3>الجذر ونوع الكلمة</h3><p>الجذر: ${w[4]} · النوع: ${w[5]||'غير محدد'}</p>`:`<h3>المرادفات</h3><p>${w[2].map(s=>`<a class="chip" style="color:inherit" href="#/search/${encodeURIComponent(s)}">${s}</a>`).join(' ')}</p><h3>مثال</h3><p class="verse" style="font-size:22px;text-align:right">${w[3]}</p>`}</div><h3>كلمات ذات صلة</h3><div class="grid">${[1,2,3].map(k=>wc((i+k)%W.length)).join('')}</div>`,w[0])}
