const Q={
verse:()=>{const v=V[Math.floor(Math.random()*V.length)],o=shuf([v[1],...shuf(V.filter(x=>x!=v)).slice(0,3).map(x=>x[1])]);return{t:'أكمل البيت',q:v[0]+' ...',o,a:v[1],ex:`${v[0]} / ${v[1]} — ${v[2]}`}},
who:()=>{const v=V[Math.floor(Math.random()*V.length)],ps=[...new Set(V.map(x=>x[2]))],o=shuf([v[2],...shuf(ps.filter(x=>x!=v[2])).slice(0,3)]);return{t:'من القائل؟',q:v[0]+' / '+v[1],o,a:v[2],ex:v[3]}},
meaning:()=>{const w=W[Math.floor(Math.random()*W.length)],o=shuf([w[1],...shuf(W.filter(x=>x!=w)).slice(0,3).map(x=>x[1])]);return{t:'ما معنى الكلمة؟',q:w[0],o,a:w[1],ex:'مثال: '+w[3]}},
rhyme:()=>{const r=FM[Math.floor(Math.random()*FM.length)];return{t:'تحدي القافية',q:'أي كلمة تُقفّي مع «'+r[0]+'»؟',o:shuf([r[1],...r[2]]),a:r[1],ex:r[0]+' و'+r[1]+' تنتهيان بالحرف نفسه.'}},
fact:()=>{const f=FACT[Math.floor(Math.random()*FACT.length)];return{t:'حقيقة أم أسطورة؟',q:f[0],o:['حقيقة','أسطورة'],a:f[1]?'حقيقة':'أسطورة',ex:f[2]}},
syn:()=>{const w=W[Math.floor(Math.random()*W.length)],a=w[2][0],bad=[...new Set(shuf(W.filter(x=>x!=w)).map(x=>x[2][0]))].filter(x=>!w[2].includes(x)).slice(0,3);return{t:'ما مرادف الكلمة؟',q:w[0],o:shuf([a,...bad]),a,ex:w[0]+' تعني: '+w[1]}},
poet:()=>{const p=P[Math.floor(Math.random()*P.length)],o=shuf([p[0],...shuf(P.filter(x=>x!=p)).slice(0,3).map(x=>x[0])]);return{t:'من هو الشاعر؟',q:p[1],o,a:p[0],ex:'هو '+p[0]+'.'}},
 root:()=>{const pool=W.filter(w=>w[4]);const w=pool[Math.floor(Math.random()*pool.length)];const wrong=shuf(pool.filter(x=>x!==w&&x[4]!==w[4])).slice(0,3).map(x=>x[4]);return{t:'تحدي الجذور',q:'ما جذر كلمة «'+w[0]+'»؟',o:shuf([w[4],...wrong]),a:w[4],ex:'معنى الكلمة: '+w[1]}},
 story:()=>{const s=S[Math.floor(Math.random()*S.length)],o=shuf([s[0],...shuf(S.filter(x=>x!==s)).slice(0,3).map(x=>x[0])]);return{t:'من عالم الحكايات',q:s[2],o,a:s[0],ex:s[3][0]}},
 quran:()=>{const pool=W.filter(w=>w[1]&&w[1].includes('الموضع:'));const w=pool.length?pool[Math.floor(Math.random()*pool.length)]:W[Math.floor(Math.random()*W.length)];const wrong=shuf(W.filter(x=>x!==w)).slice(0,3).map(x=>x[1]);return{t:'مفردات قرآنية',q:'ما معنى «'+w[0]+'»؟',o:shuf([w[1],...wrong]),a:w[1],ex:'للتفسير الدقيق تُراجع الآية في سياقها وتفسيرها.'}},
 type:()=>{const pool=W.filter(w=>w[5]);const w=pool[Math.floor(Math.random()*pool.length)];const opts=['اسم','صفة','فعل','حرف'];return{t:'نوع الكلمة',q:'ما نوع كلمة «'+w[0]+'» بحسب الفهرس؟',o:shuf([w[5],...shuf(opts.filter(x=>x!==w[5])).slice(0,3)]),a:w[5],ex:'الجذر المسجل: '+w[4]}}};
let G=null;
function play(){const st=ls('hk_st',{best:0,streak:0,last:''});
return wrap(`<div class="stat"><span>🔥 سلسلة الأيام: ${st.streak}</span><span>🏆 أفضل نتيجة: ${st.best}</span></div><div class="game" style="margin-top:20px">${[['daily','تحدي اليوم','10 أسئلة جديدة كل يوم'],['verse','أكمل البيت','أكمل بيتاً مشهوراً'],['who','من القائل؟','خمّن الشاعر'],['rhyme','تحدي القافية','اختر الكلمة المقفّاة'],['meaning','ما معنى الكلمة؟','اختر التعريف'],['fact','حقيقة أم أسطورة؟','ميّز بين الحقيقة والخيال'],['syn','ما مرادف الكلمة؟','اختر المرادف الصحيح'],['poet','من هو الشاعر؟','تعرّف على الشاعر من نبذته'],['root','تحدي الجذور','اكتشف جذور الكلمات العربية'],['quran','مفردات قرآنية','افهم معاني الكلمات القرآنية'],['story','من عالم الحكايات','تعرّف على القصة من وصفها'],['type','نوع الكلمة','اسم أم صفة؟']].map(g=>`<button class="card" style="text-align:center" onclick="start('${g[0]}')"><h3>${g[1]}</h3><p>${g[2]}</p></button>`).join('')}</div><div id="qz"></div>`,'اللعب واختبر معرفتك')}
function start(m){let qs=[];if(m=='daily'){const r=rng(day()),k=Object.keys(Q);const _r=Math.random;Math.random=r;qs=[...Array(10)].map((_,i)=>Q[k[i%k.length]]());Math.random=_r}else qs=[...Array(10)].map(()=>Q[m]());G={m,qs,i:0,s:0};ask();$('#qz').scrollIntoView({behavior:'smooth'})}
function ask(){const q=G.qs[G.i];$('#qz').innerHTML=`<div class="q"><div class="meta">${q.t} · ${G.i+1}/10</div><h3 style="margin:8px 0 14px;font-size:26px">${q.q}</h3>${q.o.map((o,k)=>`<button class="opt" onclick="pick(${k})">${o}</button>`).join('')}<div id="fbk"></div></div>`}
function pick(k){const q=G.qs[G.i],b=document.querySelectorAll('.opt'),ok=q.o[k]==q.a;if(ok)G.s++;b.forEach((x,j)=>{x.disabled=true;if(q.o[j]==q.a)x.classList.add('ok');else if(j==k)x.classList.add('no')});
$('#fbk').innerHTML=`<div class="ex">${ok?'✓ أحسنت! ':'✗ الإجابة: '+q.a+'. '}${q.ex}</div><button class="btn" style="margin-top:12px" onclick="nxt()">${G.i<9?'التالي':'النتيجة'}</button>`}
function nxt(){G.i++;if(G.i<10)return ask();const st=ls('hk_st',{best:0,streak:0,last:''});st.best=Math.max(st.best,G.s);
if(G.m=='daily'&&st.last!=dkey()){const y=new Date(Date.now()-864e5).toISOString().slice(0,10);st.streak=st.last==y?st.streak+1:1;st.last=dkey()}ss('hk_st',st);
const t=`حصلت على ${G.s}/10 في حكاية ${G.m=='daily'?'(تحدي اليوم)':''} 🪶 ${location.href.split('#')[0]}`;
$('#qz').innerHTML=`<div class="q" style="text-align:center"><h3 style="font-size:34px">${G.s}/10</h3><p>${G.s>3?'ممتاز! ثقافتك واسعة.':'محاولة جيدة، جرّب مرة أخرى.'}</p><button class="btn" onclick="navigator.clipboard.writeText(${E(JSON.stringify(t)).replace(/'/g,'&#39;')}).then(()=>this.textContent='تم النسخ ✓')">شارك نتيجتك</button> <button class="ghost" onclick="start('${G.m}')">العب مجدداً</button></div>`}
// ---- Shared visitor ratings and comments (Supabase REST API)
const HIKAYA_SUPABASE_URL = 'https://vnxfclkjsigxrczopwqc.supabase.co';
const HIKAYA_SUPABASE_PUBLISHABLE_KEY = 'sb_publishable_TbBiD6VXQ8DviQYFW8YZNQ_o-WKaBkz';
const HIKAYA_REVIEWS_ENDPOINT = `${HIKAYA_SUPABASE_URL}/rest/v1/reviews`;
function reviewHeaders(extra={}) { return { apikey:HIKAYA_SUPABASE_PUBLISHABLE_KEY, Authorization:`Bearer ${HIKAYA_SUPABASE_PUBLISHABLE_KEY}`, ...extra }; }
function reviewStars(n){return '★'.repeat(Number(n)||0)+'☆'.repeat(5-(Number(n)||0));}
function reviewDate(value){try{return new Date(value).toLocaleDateString('ar',{year:'numeric',month:'short',day:'numeric'})}catch(e){return ''}}
async function loadHikayaReviews(){
 const summary=$('#reviewsSummary'),list=$('#reviewsList'); if(!summary||!list)return;
 try{
  const response=await fetch(`${HIKAYA_REVIEWS_ENDPOINT}?select=id,name,rating,comment,created_at&approved=eq.true&order=created_at.desc&limit=100`,{headers:reviewHeaders({'Accept':'application/json'})});
  if(!response.ok)throw new Error(`HTTP ${response.status}`);
  const rows=await response.json();
  if(!rows.length){summary.innerHTML='<strong>لا توجد تقييمات منشورة بعد</strong><span>كن أول من يشارك رأيه في حكاية.</span>';list.innerHTML='<p class="meta">ستظهر التعليقات هنا بعد مراجعتها ونشرها.</p>';return;}
  const avg=rows.reduce((a,r)=>a+Number(r.rating||0),0)/rows.length;
  summary.innerHTML=`<strong class="review-average">${avg.toLocaleString('ar',{maximumFractionDigits:1})} / 5</strong><span class="review-stars" aria-label="متوسط التقييم">${reviewStars(Math.round(avg))}</span><span>${rows.length.toLocaleString('ar')} تقييم منشور</span>`;
  list.innerHTML=rows.map(r=>`<article class="review-item"><div class="review-item-top"><strong>${escapeReviewText(r.name)}</strong><time>${reviewDate(r.created_at)}</time></div><div class="review-stars" aria-label="${Number(r.rating)} من 5">${reviewStars(r.rating)}</div><p>${escapeReviewText(r.comment).replace(/\n/g,'<br>')}</p></article>`).join('');
 }catch(err){summary.textContent='تعذّر تحميل التقييمات حاليًا.';list.innerHTML='<p class="meta">تحقق من إعداد جدول reviews وسياسات الوصول في Supabase، ثم أعد تحميل الصفحة.</p>';console.error('Hikaya reviews load failed:',err);}
}
function escapeReviewText(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
async function submitHikayaReview(event,form){
 event.preventDefault();const feedback=$('#reviewFeedback'),button=form.querySelector('button[type="submit"]');
 const name=String(form.reviewName.value||'').trim(),comment=String(form.reviewComment.value||'').trim(),rating=Number(new FormData(form).get('rating'));
 if(name.length<1||name.length>60||comment.length<3||comment.length>1000||rating<1||rating>5){feedback.textContent='يرجى التحقق من الاسم والتقييم والتعليق.';return;}
 button.disabled=true;feedback.textContent='جارٍ إرسال تقييمك…';
 try{
  const response=await fetch(HIKAYA_REVIEWS_ENDPOINT,{method:'POST',headers:reviewHeaders({'Content-Type':'application/json','Prefer':'return=minimal'}),body:JSON.stringify({name,rating,comment,approved:false})});
  if(!response.ok){let detail='';try{detail=(await response.json()).message||''}catch(e){}throw new Error(detail||`HTTP ${response.status}`)}
  form.reset();const defaultStar=form.querySelector('input[name="rating"][value="5"]');if(defaultStar)defaultStar.checked=true;
  feedback.textContent='شكرًا لك! وصل تقييمك، وسيظهر بعد مراجعته من صاحب الموقع.';
 }catch(err){feedback.textContent='لم نتمكن من إرسال التقييم. تأكد من إعداد جدول reviews وسياسات Supabase ثم حاول مجددًا.';console.error('Hikaya review submit failed:',err)}finally{button.disabled=false;}
}

// ---- router
function reveal(){const els=document.querySelectorAll('.rv:not(.in)');if(!('IntersectionObserver'in window)){els.forEach(e=>e.classList.add('in'));return}
const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');o.unobserve(e.target)}}),{threshold:.1});els.forEach(e=>o.observe(e))}
function route(){const [,r,a]=(location.hash||'#/').split('/'),x=a?decodeURIComponent(a):'';
const m={'':home,words,word:()=>word(+x),poetry:()=>poetry(x),poem:()=>poem(+x),stories,story:()=>story(+x),poets,fav:fav_,search:()=>search(a),play,about};
app.innerHTML=(m[r||'']||home)();if((r||'')==='')setTimeout(loadHikayaReviews,0);$('#nav').innerHTML=NAV.map(n=>`<a href="${n[0]}" class="${(location.hash||'#/')==n[0]||(n[0]!='#/'&&(location.hash||'').startsWith(n[0]))?'on':''}">${n[1]}</a>`).join('');scrollTo(0,0);reveal()}
$('#srch').onclick=()=>{const q=prompt('ابحث عن كلمة، بيت شعر، شاعر أو قصة');if(q)location.hash='#/search/'+encodeURIComponent(q)};
// Always start in light mode, regardless of system preference or a previously saved theme.
const sth=v=>{document.documentElement.dataset.theme=v;$('#theme').textContent=v==='dark'?'☀️':'🌙';$('#theme').setAttribute('aria-label',v==='dark'?'التبديل إلى الوضع الفاتح':'التبديل إلى الوضع الداكن')};
sth('light');
$('#theme').onclick=()=>sth(document.documentElement.dataset.theme==='dark'?'light':'dark');
document.addEventListener('input',e=>{if(e.target&&e.target.name==='message'){const c=$('#messageCount');if(c)c.textContent=e.target.value.length}});
// Welcome notice is shown on first visit and can be dismissed with X or the button.
(()=>{const modal=document.getElementById('testNotice');if(!modal)return;const close=()=>{modal.hidden=true;try{localStorage.setItem(TEST_NOTICE_KEY,'1')}catch(e){}};try{if(!localStorage.getItem(TEST_NOTICE_KEY))modal.hidden=false}catch(e){modal.hidden=false}document.getElementById('closeNotice')?.addEventListener('click',close);document.getElementById('continueNotice')?.addEventListener('click',close);modal.addEventListener('click',e=>{if(e.target===modal)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden)close()});const owner=document.getElementById('noticeOwnerName');if(owner)owner.textContent=SITE_OWNER;})();
addEventListener('hashchange',route);cnt();route();
